.credit-layer > span { font: 800 20px/1 var(--font-display); letter-spacing: .12em; color: var(--sage); }
.credit-layer h3 { font: 800 35px/1.1 var(--font-display); color: var(--forest); }
.credit-layer p { font-size: 25px; line-height: 1.35; color: var(--charcoal); }

.ingredient-track { position: relative; display: grid; grid-template-columns: repeat(4, 1fr); gap: 42px; }
