}
.cash-builder-overlay[hidden] { display: none; }
.cash-builder-shell { position: absolute; overflow: visible; }
.cash-builder-surface {
  position: relative; width: 720px; height: 900px; overflow: hidden;
  transform-origin: top left; background: var(--mist); color: var(--charcoal);
  border-radius: 22px; box-shadow: 0 42px 100px rgba(0, 0, 0, .42);
